import { sql } from "drizzle-orm"
import { boolean, customType, index, integer, pgTable, primaryKey, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core"
import { user } from "./auth-schema.js"

// Accounts, sessions and sign-in methods. Generated by the auth CLI (see README), don't edit by hand
export * from "./auth-schema.js"

// The public side of an account
export const profile = pgTable("profile", {
  userId: text("user_id").primaryKey().references(() => user.id, { onDelete: "cascade" }),
  username: text("username").notNull(),
  // a few words about themselves, shown on their profile
  bio: text("bio").notNull().default(""),
  // experience: what their level is worked out from (see shared/progression.ts)
  xp: integer("xp").notNull().default(0),
  // their multiplayer rating; 1000 is where everyone starts
  elo: integer("elo").notNull().default(1000),
  // every game they have started in any mode, finished or not, and the seconds they have spent in them
  gamesStarted: integer("games_started").notNull().default(0),
  playSeconds: integer("play_seconds").notNull().default(0),
}, (table) => [
  // usernames are unique regardless of capitalisation
  uniqueIndex("profile_username_lower_idx").on(sql`lower(${table.username})`),
])

const bytea = customType<{ data: Buffer }>({ dataType: () => "bytea" })

// Uploaded profile photos. Kept in the database for now; file storage would take over once the site is hosted for real
export const avatar = pgTable("avatar", {
  userId: text("user_id").primaryKey().references(() => user.id, { onDelete: "cascade" }),
  contentType: text("content_type").notNull(),
  data: bytea("data").notNull(),
})

// One row per finished game of a signed-in player
export const gameResult = pgTable("game_result", {
  id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  rows: integer("rows").notNull(),
  cols: integer("cols").notNull(),
  mines: integer("mines").notNull(),
  won: boolean("won").notNull(),
  durationSeconds: integer("duration_seconds").notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("game_result_user_idx").on(table.userId),
])

// A multiplayer game someone cleared: one row per player who finished. The leaderboards are built from these,
// because the server runs those games itself and so the times can be trusted
export const multiplayerResult = pgTable("multiplayer_result", {
  id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  rows: integer("rows").notNull(),
  cols: integer("cols").notNull(),
  mines: integer("mines").notNull(),
  durationMs: integer("duration_ms").notNull(),
  mineHits: integer("mine_hits").notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("multiplayer_result_board_idx").on(table.rows, table.cols, table.mines, table.durationMs),
])

// A player's go at one day's challenge. The row appears when they first start that day, which is when their
// clock starts; the result is filled in when they clear the board
export const dailyAttempt = pgTable("daily_attempt", {
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  // YYYY-MM-DD, in UTC
  date: text("date").notNull(),
  startedAt: timestamp("started_at").notNull(),
  durationMs: integer("duration_ms"),
  mineHits: integer("mine_hits"),
}, (table) => [
  primaryKey({ columns: [table.userId, table.date] }),
])
